if (!empty($data['boxnow_locker']['id'])) {
	$this->load->model('extension/shipping/boxnow');
	$this->model_extension_shipping_boxnow->saveOrderLocker($order_id, $data['boxnow_locker']);
}

if (isset($order_info['shipping_code']) && $order_info['shipping_code'] == 'boxnow.boxnow') {
	$boxnow_query = $this->db->query("SELECT `locker_id`, `locker_label` FROM `" . DB_PREFIX . "boxnow_order` WHERE `order_id` = '" . (int)$order_id . "' LIMIT 1");

	if ($boxnow_query->num_rows) {
		$boxnow_label = $boxnow_query->row['locker_label'] ? $boxnow_query->row['locker_label'] : $boxnow_query->row['locker_id'];
		$data['shipping_method'] .= '<br /><strong>BOX NOW:</strong> ' . htmlspecialchars($boxnow_label, ENT_QUOTES, 'UTF-8') . ' (#' . htmlspecialchars($boxnow_query->row['locker_id'], ENT_QUOTES, 'UTF-8') . ')';
	}
}

if (isset($order_info['shipping_code']) && $order_info['shipping_code'] == 'boxnow.boxnow') {
	$boxnow_query = $this->db->query("SELECT `locker_id`, `locker_label` FROM `" . DB_PREFIX . "boxnow_order` WHERE `order_id` = '" . (int)$this->request->get['order_id'] . "' LIMIT 1");

	if ($boxnow_query->num_rows) {
