		$data['shipping_method'] .= '<br /><small><strong>BOX NOW:</strong> ' . htmlspecialchars($boxnow_label, ENT_QUOTES, 'UTF-8') . ' (#' . htmlspecialchars($boxnow_query->row['locker_id'], ENT_QUOTES, 'UTF-8') . ')</small>';
	}
}

$this->load->language('extension/shipping/boxnow');

$data['boxnow_available'] = false;

foreach ($data['shipping_methods'] as $boxnow_shipping_method) {
	if (!empty($boxnow_shipping_method['quote'])) {
		foreach ($boxnow_shipping_method['quote'] as $boxnow_quote) {
			if (isset($boxnow_quote['code']) && $boxnow_quote['code'] == 'boxnow.boxnow') {
				$data['boxnow_available'] = true;
				break 2;
			}
		}
	}
}

if ($data['code'] != 'boxnow.boxnow') {
	unset($this->session->data['boxnow_locker']);
}

