$data['boxnow_partner_id'] = (string)$this->config->get('boxnow_widget_partner_id');
$data['boxnow_widget_url'] = $this->config->get('boxnow_widget_url') ? (string)$this->config->get('boxnow_widget_url') : 'https://widget-cdn.boxnow.hr/map-widget/client/v5.js';
