$data['boxnow_widget_error'] = $this->language->get('error_widget');

if (isset($this->request->post['shipping_method']) && $this->request->post['shipping_method'] == 'boxnow.boxnow') {
	$this->load->language('extension/shipping/boxnow');

	$boxnow_locker_id = isset($this->request->post['boxnow_locker_id']) ? preg_replace('/[^A-Za-z0-9_-]/', '', trim($this->request->post['boxnow_locker_id'])) : (isset($this->session->data['boxnow_locker']['id']) ? $this->session->data['boxnow_locker']['id'] : '');
	$boxnow_locker_label = isset($this->request->post['boxnow_locker_label']) ? utf8_substr(trim(strip_tags($this->request->post['boxnow_locker_label'])), 0, 255) : (isset($this->session->data['boxnow_locker']['label']) ? $this->session->data['boxnow_locker']['label'] : '');
	$boxnow_locker_postcode = isset($this->request->post['boxnow_locker_postcode']) ? utf8_substr(preg_replace('/[^0-9A-Za-z -]/', '', trim($this->request->post['boxnow_locker_postcode'])), 0, 32) : (isset($this->session->data['boxnow_locker']['postcode']) ? $this->session->data['boxnow_locker']['postcode'] : '');

	if ($boxnow_locker_id == '') {
		$json['error']['warning'] = $this->language->get('error_locker');
	} else {
		$this->session->data['boxnow_locker'] = array(
			'id'       => utf8_substr($boxnow_locker_id, 0, 64),
			'label'    => $boxnow_locker_label,
			'postcode' => $boxnow_locker_postcode
		);
	}
} elseif (isset($this->request->post['shipping_method'])) {
	unset($this->session->data['boxnow_locker']);
}

$this->load->language('extension/shipping/boxnow');

$data['boxnow_available'] = false;

foreach ($data['shipping_methods'] as $boxnow_shipping_method) {
