$data['boxnow_error'] = $this->language->get('error_locker');
$data['boxnow_save_error'] = $this->language->get('error_save_locker');
$data['boxnow_widget_error'] = $this->language->get('error_widget');

if (isset($this->request->post['shipping_method']) && $this->request->post['shipping_method'] == 'boxnow.boxnow') {
	$boxnow_locker_id = isset($this->request->post['boxnow_locker_id']) ? preg_replace('/[^A-Za-z0-9_-]/', '', trim($this->request->post['boxnow_locker_id'])) : '';

	if ($boxnow_locker_id != '') {
		$this->session->data['boxnow_locker'] = array(
			'id'       => utf8_substr($boxnow_locker_id, 0, 64),
			'label'    => isset($this->request->post['boxnow_locker_label']) ? utf8_substr(trim(strip_tags($this->request->post['boxnow_locker_label'])), 0, 255) : '',
			'postcode' => isset($this->request->post['boxnow_locker_postcode']) ? utf8_substr(preg_replace('/[^0-9A-Za-z -]/', '', trim($this->request->post['boxnow_locker_postcode'])), 0, 32) : ''
		);
