			'label'    => isset($this->request->post['boxnow_locker_label']) ? utf8_substr(trim(strip_tags($this->request->post['boxnow_locker_label'])), 0, 255) : (isset($this->session->data['boxnow_locker']['label']) ? $this->session->data['boxnow_locker']['label'] : ''),
			'postcode' => isset($this->request->post['boxnow_locker_postcode']) ? utf8_substr(preg_replace('/[^0-9A-Za-z -]/', '', trim($this->request->post['boxnow_locker_postcode'])), 0, 32) : (isset($this->session->data['boxnow_locker']['postcode']) ? $this->session->data['boxnow_locker']['postcode'] : '')
		);
	}
}

$data['boxnow_create'] = '';
$data['boxnow_label'] = '';
$data['boxnow_parcel_id'] = '';
$data['boxnow_tracking_url'] = '';

if (isset($order_info['shipping_code']) && $order_info['shipping_code'] == 'boxnow.boxnow') {
	$this->load->language('extension/shipping/boxnow');
	$this->load->model('extension/shipping/boxnow');

	$boxnow_order = $this->model_extension_shipping_boxnow->getOrder((int)$this->request->get['order_id']);

	if ($boxnow_order) {
		$data['boxnow_create'] = $this->url->link('extension/shipping/boxnow/createShipment', 'token=' . $this->session->data['token'] . '&order_id=' . (int)$this->request->get['order_id'], true);
		$data['boxnow_label'] = $this->url->link('extension/shipping/boxnow/label', 'token=' . $this->session->data['token'] . '&order_id=' . (int)$this->request->get['order_id'], true);
		$data['boxnow_parcel_id'] = $boxnow_order['parcel_id'];
		$data['boxnow_tracking_url'] = $this->model_extension_shipping_boxnow->getTrackingUrl($boxnow_order['parcel_id']);
		$boxnow_display = $boxnow_order['locker_label'] ? $boxnow_order['locker_label'] : $boxnow_order['locker_id'];

		$data['shipping_method'] .= '<br /><small><strong>BOX NOW:</strong> ' . htmlspecialchars($boxnow_display, ENT_QUOTES, 'UTF-8') . ' (#' . htmlspecialchars($boxnow_order['locker_id'], ENT_QUOTES, 'UTF-8') . ')</small>';
		$data['shipping_method'] .= '<div style="margin-top:8px;">';

		if ($data['boxnow_parcel_id']) {
			$data['shipping_method'] .= '<span class="label label-success">Parcel: ' . htmlspecialchars($data['boxnow_parcel_id'], ENT_QUOTES, 'UTF-8') . '</span> ';

			if ($data['boxnow_tracking_url']) {
				$data['shipping_method'] .= '<a href="' . htmlspecialchars($data['boxnow_tracking_url'], ENT_QUOTES, 'UTF-8') . '" target="_blank" rel="noopener" class="btn btn-default btn-xs"><i class="fa fa-map-marker"></i> ' . $this->language->get('button_tracking') . '</a> ';
			}

			$data['shipping_method'] .= '<a href="' . $data['boxnow_label'] . '" target="_blank" class="btn btn-info btn-xs"><i class="fa fa-print"></i> ' . $this->language->get('button_label') . '</a>';
		} else {
			$data['shipping_method'] .= '<button type="button" id="button-boxnow-create" data-loading-text="' . htmlspecialchars($this->language->get('text_loading'), ENT_QUOTES, 'UTF-8') . '" class="btn btn-success btn-xs"><i class="fa fa-truck"></i> ' . $this->language->get('button_create_shipment') . '</button>';
		}

		$data['shipping_method'] .= '</div>';
	}
